# Application Monitoring System - Week 8 Performance Implementation\n# Monitor Legislativo v4 - Comprehensive System Monitoring\n# =========================================================\n# Real-time application monitoring with Railway-specific optimizations\n# and Brazilian legislative workflow performance tracking\n\nlibrary(shiny)\nlibrary(jsonlite)\nlibrary(httr)\nlibrary(dplyr)\n\n# Global monitoring configuration\n.MONITORING_CONFIG <- list(\n  # System monitoring intervals\n  health_check_interval_seconds = 60,\n  performance_sampling_seconds = 30,\n  memory_check_interval_seconds = 45,\n  \n  # Railway-specific thresholds\n  memory_warning_mb = 2304,        # 75% of 3GB\n  memory_critical_mb = 2764,       # 90% of 3GB\n  cpu_warning_percent = 70,\n  cpu_critical_percent = 85,\n  response_time_warning_ms = 2000,\n  response_time_critical_ms = 5000,\n  \n  # Brazilian academic context\n  peak_hours = list(\n    start = 9,   # 9 AM\n    end = 17     # 5 PM\n  ),\n  academic_days = 1:5,  # Monday to Friday\n  timezone = \"America/Sao_Paulo\",\n  \n  # Monitoring features\n  real_time_alerts = TRUE,\n  performance_logging = TRUE,\n  uptime_tracking = TRUE,\n  user_session_monitoring = TRUE,\n  database_performance_monitoring = TRUE,\n  \n  # Alert configuration\n  alert_cooldown_minutes = 15,\n  max_alerts_per_hour = 10,\n  alert_persistence_hours = 24\n)\n\n# Global monitoring state\n.MONITORING_STATE <- list(\n  system_start_time = Sys.time(),\n  last_health_check = NULL,\n  current_alerts = list(),\n  performance_history = list(),\n  uptime_percentage = 100,\n  \n  # Real-time metrics\n  current_memory_mb = 0,\n  current_cpu_percent = 0,\n  active_sessions = 0,\n  database_connections = 0,\n  cache_hit_rate = 0,\n  \n  # Counters\n  total_requests = 0,\n  successful_requests = 0,\n  failed_requests = 0,\n  total_errors = 0\n)\n\n#' Initialize Application Monitoring System\n#' \n#' Sets up comprehensive monitoring for Brazilian Legislative Monitor\n#' with Railway platform optimizations and academic usage patterns.\n#' \n#' @param enable_real_time Logical. Enable real-time monitoring\n#' @param enable_alerts Logical. Enable alerting system\n#' @param custom_thresholds List. Custom alert thresholds\n#' @return List with monitoring initialization status\n#' @export\ninit_application_monitoring <- function(enable_real_time = TRUE,\n                                       enable_alerts = TRUE,\n                                       custom_thresholds = NULL) {\n  \n  cat(\"\ud83d\udcc8 Initializing Application Monitoring System\\n\")\n  \n  tryCatch({\n    # Apply custom thresholds if provided\n    if (!is.null(custom_thresholds)) {\n      .MONITORING_CONFIG <<- modifyList(.MONITORING_CONFIG, custom_thresholds)\n    }\n    \n    # Initialize monitoring state\n    .MONITORING_STATE$system_start_time <<- Sys.time()\n    .MONITORING_STATE$last_health_check <<- Sys.time()\n    \n    # Set up performance monitoring\n    if (enable_real_time) {\n      setup_real_time_monitoring()\n    }\n    \n    # Initialize alerting system\n    if (enable_alerts) {\n      setup_alerting_system()\n    }\n    \n    # Set up Railway-specific monitoring\n    setup_railway_monitoring()\n    \n    # Initialize Brazilian academic context monitoring\n    setup_academic_context_monitoring()\n    \n    # Start background monitoring tasks\n    start_background_monitoring()\n    \n    cat(\"\u2705 Application Monitoring System initialized successfully\\n\")\n    cat(\"   - Real-time monitoring:\", enable_real_time, \"\\n\")\n    cat(\"   - Alerting enabled:\", enable_alerts, \"\\n\")\n    cat(\"   - Memory threshold:\", .MONITORING_CONFIG$memory_warning_mb, \"MB\\n\")\n    cat(\"   - Response time threshold:\", .MONITORING_CONFIG$response_time_warning_ms, \"ms\\n\")\n    \n    return(list(\n      status = \"success\",\n      monitoring_active = TRUE,\n      config = .MONITORING_CONFIG,\n      start_time = .MONITORING_STATE$system_start_time\n    ))\n    \n  }, error = function(e) {\n    cat(\"\u274c Application monitoring initialization failed:\", e$message, \"\\n\")\n    return(list(status = \"error\", error = e$message))\n  })\n}\n\n#' Track Application Performance Metrics\n#' \n#' Records comprehensive performance metrics with Brazilian legislative\n#' context and Railway platform considerations.\n#' \n#' @param metric_type Character. Type of metric to track\n#' @param value Numeric. Metric value\n#' @param metadata List. Additional metric metadata\n#' @param session_id Character. User session identifier\n#' @export\ntrack_performance_metric <- function(metric_type, value, \n                                   metadata = NULL, \n                                   session_id = NULL) {\n  \n  timestamp <- Sys.time()\n  \n  # Create performance record\n  performance_record <- list(\n    timestamp = timestamp,\n    metric_type = metric_type,\n    value = value,\n    metadata = metadata,\n    session_id = session_id,\n    hour_of_day = as.numeric(format(timestamp, \"%H\")),\n    day_of_week = weekdays(timestamp),\n    is_peak_hour = is_academic_peak_hour(timestamp),\n    brazilian_timezone = format(timestamp, \"%Y-%m-%d %H:%M:%S %Z\", tz = .MONITORING_CONFIG$timezone)\n  )\n  \n  # Store in performance history\n  .MONITORING_STATE$performance_history[[length(.MONITORING_STATE$performance_history) + 1]] <<- performance_record\n  \n  # Update real-time counters\n  update_real_time_counters(metric_type, value)\n  \n  # Check for performance alerts\n  check_performance_thresholds(metric_type, value, performance_record)\n  \n  # Log performance data if enabled\n  if (.MONITORING_CONFIG$performance_logging) {\n    log_performance_metric(performance_record)\n  }\n  \n  # Cleanup old performance data (keep last 10000 records)\n  if (length(.MONITORING_STATE$performance_history) > 10000) {\n    .MONITORING_STATE$performance_history <<- tail(.MONITORING_STATE$performance_history, 10000)\n  }\n}\n\n#' Monitor System Health\n#' \n#' Comprehensive system health check optimized for Railway hosting\n#' and Brazilian legislative document processing workloads.\n#' \n#' @param detailed_check Logical. Perform detailed health analysis\n#' @return List with comprehensive health status\n#' @export\nmonitor_system_health <- function(detailed_check = TRUE) {\n  \n  cat(\"\ud83c\udf21\ufe0f Performing system health check...\\n\")\n  \n  health_check_start <- Sys.time()\n  \n  tryCatch({\n    # Basic system metrics\n    basic_health <- get_basic_system_health()\n    \n    # Memory analysis\n    memory_health <- analyze_memory_health()\n    \n    # Database health\n    database_health <- check_database_health()\n    \n    # Cache performance health\n    cache_health <- check_cache_health()\n    \n    # Application responsiveness\n    response_health <- check_response_health()\n    \n    # Brazilian academic context health\n    academic_health <- check_academic_context_health()\n    \n    # Railway-specific health checks\n    railway_health <- check_railway_health()\n    \n    # Detailed analysis if requested\n    detailed_analysis <- NULL\n    if (detailed_check) {\n      detailed_analysis <- perform_detailed_health_analysis()\n    }\n    \n    # Calculate overall health score\n    overall_health_score <- calculate_overall_health_score(\n      basic_health, memory_health, database_health, \n      cache_health, response_health, academic_health, railway_health\n    )\n    \n    # Generate health recommendations\n    recommendations <- generate_health_recommendations(\n      basic_health, memory_health, database_health, cache_health\n    )\n    \n    health_check_duration <- as.numeric(difftime(Sys.time(), health_check_start, units = \"secs\")) * 1000\n    \n    # Update monitoring state\n    .MONITORING_STATE$last_health_check <<- Sys.time()\n    \n    health_report <- list(\n      timestamp = Sys.time(),\n      check_duration_ms = health_check_duration,\n      overall_score = overall_health_score,\n      \n      # Component health\n      basic_health = basic_health,\n      memory_health = memory_health,\n      database_health = database_health,\n      cache_health = cache_health,\n      response_health = response_health,\n      academic_health = academic_health,\n      railway_health = railway_health,\n      \n      # Analysis and recommendations\n      detailed_analysis = detailed_analysis,\n      recommendations = recommendations,\n      \n      # System context\n      uptime_hours = calculate_uptime_hours(),\n      is_peak_hour = is_academic_peak_hour(),\n      timezone = .MONITORING_CONFIG$timezone\n    )\n    \n    # Track health check performance\n    track_performance_metric(\"health_check_duration\", health_check_duration)\n    \n    # Generate alerts if necessary\n    check_health_alerts(health_report)\n    \n    cat(\"\u2705 System health check completed - Overall Score:\", round(overall_health_score, 1), \"/100\\n\")\n    \n    return(health_report)\n    \n  }, error = function(e) {\n    cat(\"\u274c System health check failed:\", e$message, \"\\n\")\n    \n    # Track health check failure\n    track_performance_metric(\"health_check_error\", 1, list(error = e$message))\n    \n    return(list(\n      status = \"error\",\n      error = e$message,\n      timestamp = Sys.time()\n    ))\n  })\n}\n\n#' Create Real-Time Monitoring Dashboard\n#' \n#' Generates comprehensive monitoring dashboard with Brazilian legislative\n#' context and Railway platform specific metrics.\n#' \n#' @param time_range_hours Numeric. Hours of data to display\n#' @param include_predictions Logical. Include performance predictions\n#' @return List with dashboard data and visualizations\n#' @export\ncreate_monitoring_dashboard <- function(time_range_hours = 24, \n                                       include_predictions = TRUE) {\n  \n  cat(\"\ud83d\udccb Creating real-time monitoring dashboard...\\n\")\n  \n  tryCatch({\n    # Get current system status\n    current_status <- get_current_system_status()\n    \n    # Performance metrics over time\n    performance_timeline <- generate_performance_timeline(time_range_hours)\n    \n    # Resource utilization analysis\n    resource_utilization <- analyze_resource_utilization(time_range_hours)\n    \n    # User activity patterns\n    user_activity_patterns <- analyze_user_activity_patterns(time_range_hours)\n    \n    # Database performance analysis\n    database_performance <- analyze_database_performance(time_range_hours)\n    \n    # Cache performance analysis\n    cache_performance <- analyze_cache_performance(time_range_hours)\n    \n    # Error tracking and analysis\n    error_analysis <- analyze_error_patterns(time_range_hours)\n    \n    # Brazilian academic context analysis\n    academic_analysis <- analyze_academic_usage_patterns(time_range_hours)\n    \n    # Railway-specific metrics\n    railway_metrics <- get_railway_specific_metrics(time_range_hours)\n    \n    # Performance predictions\n    predictions <- NULL\n    if (include_predictions) {\n      predictions <- generate_performance_predictions()\n    }\n    \n    # Alert summary\n    alert_summary <- get_alert_summary(time_range_hours)\n    \n    dashboard_data <- list(\n      # Current status\n      current_status = current_status,\n      \n      # Time series data\n      performance_timeline = performance_timeline,\n      resource_utilization = resource_utilization,\n      user_activity_patterns = user_activity_patterns,\n      \n      # Component analysis\n      database_performance = database_performance,\n      cache_performance = cache_performance,\n      error_analysis = error_analysis,\n      \n      # Context-specific analysis\n      academic_analysis = academic_analysis,\n      railway_metrics = railway_metrics,\n      \n      # Predictions and alerts\n      predictions = predictions,\n      alert_summary = alert_summary,\n      \n      # Dashboard metadata\n      generated_at = Sys.time(),\n      time_range_hours = time_range_hours,\n      data_points = length(.MONITORING_STATE$performance_history)\n    )\n    \n    cat(\"\u2705 Monitoring dashboard created successfully\\n\")\n    cat(\"   - Time range:\", time_range_hours, \"hours\\n\")\n    cat(\"   - Data points:\", dashboard_data$data_points, \"\\n\")\n    cat(\"   - Active alerts:\", length(dashboard_data$alert_summary$active_alerts), \"\\n\")\n    \n    return(dashboard_data)\n    \n  }, error = function(e) {\n    cat(\"\u274c Dashboard creation failed:\", e$message, \"\\n\")\n    return(list(status = \"error\", error = e$message))\n  })\n}\n\n# Helper functions for monitoring implementation\n\n#' Setup real-time monitoring\nsetup_real_time_monitoring <- function() {\n  \n  cat(\"\ud83d\udd04 Setting up real-time monitoring...\\n\")\n  \n  # In production, this would set up:\n  # - Background processes for metric collection\n  # - WebSocket connections for real-time updates\n  # - Performance sampling intervals\n  \n  cat(\"   - Performance sampling every\", .MONITORING_CONFIG$performance_sampling_seconds, \"seconds\\n\")\n  cat(\"   - Memory checks every\", .MONITORING_CONFIG$memory_check_interval_seconds, \"seconds\\n\")\n}\n\n#' Setup alerting system\nsetup_alerting_system <- function() {\n  \n  cat(\"\ud83d\udd14 Setting up alerting system...\\n\")\n  \n  # Initialize alert state\n  .MONITORING_STATE$current_alerts <<- list()\n  \n  cat(\"   - Memory warning threshold:\", .MONITORING_CONFIG$memory_warning_mb, \"MB\\n\")\n  cat(\"   - Response time warning:\", .MONITORING_CONFIG$response_time_warning_ms, \"ms\\n\")\n  cat(\"   - Alert cooldown:\", .MONITORING_CONFIG$alert_cooldown_minutes, \"minutes\\n\")\n}\n\n#' Setup Railway-specific monitoring\nsetup_railway_monitoring <- function() {\n  \n  cat(\"\ud83d\ude86 Setting up Railway platform monitoring...\\n\")\n  \n  # Configure Railway-specific metrics\n  railway_config <- list(\n    memory_limit_mb = 3072,\n    cpu_limit_cores = 1.5,\n    deployment_region = Sys.getenv(\"RAILWAY_REGION\", \"unknown\"),\n    service_id = Sys.getenv(\"RAILWAY_SERVICE_ID\", \"unknown\")\n  )\n  \n  cat(\"   - Memory limit:\", railway_config$memory_limit_mb, \"MB\\n\")\n  cat(\"   - CPU limit:\", railway_config$cpu_limit_cores, \"cores\\n\")\n}\n\n#' Setup academic context monitoring\nsetup_academic_context_monitoring <- function() {\n  \n  cat(\"\ud83c\udf93 Setting up Brazilian academic context monitoring...\\n\")\n  \n  # Configure academic usage patterns\n  academic_config <- list(\n    peak_hours = .MONITORING_CONFIG$peak_hours,\n    academic_days = .MONITORING_CONFIG$academic_days,\n    timezone = .MONITORING_CONFIG$timezone\n  )\n  \n  cat(\"   - Peak hours:\", academic_config$peak_hours$start, \"h -\", academic_config$peak_hours$end, \"h\\n\")\n  cat(\"   - Academic days: Monday - Friday\\n\")\n  cat(\"   - Timezone:\", academic_config$timezone, \"\\n\")\n}\n\n#' Start background monitoring tasks\nstart_background_monitoring <- function() {\n  \n  cat(\"\u26a1 Starting background monitoring tasks...\\n\")\n  \n  # In production, this would start:\n  # - Periodic health checks\n  # - Performance metric collection\n  # - Alert processing\n  # - Data cleanup tasks\n  \n  cat(\"   - Health checks every\", .MONITORING_CONFIG$health_check_interval_seconds, \"seconds\\n\")\n}\n\n#' Get basic system health metrics\nget_basic_system_health <- function() {\n  \n  # Get basic R system information\n  memory_info <- gc()\n  current_memory_mb <- sum(memory_info[, \"used\"]) * 0.048576  # Approximate conversion\n  \n  # Update monitoring state\n  .MONITORING_STATE$current_memory_mb <<- current_memory_mb\n  \n  basic_health <- list(\n    memory_usage_mb = current_memory_mb,\n    memory_usage_percent = (current_memory_mb / 3072) * 100,\n    r_version = R.version.string,\n    platform = R.version$platform,\n    system_time = Sys.time(),\n    uptime_hours = calculate_uptime_hours(),\n    \n    # System load indicators\n    gc_info = memory_info,\n    \n    # Session information\n    session_info = list(\n      r_session_id = Sys.getpid(),\n      working_directory = getwd()\n    )\n  )\n  \n  return(basic_health)\n}\n\n#' Analyze memory health with Railway constraints\nanalyze_memory_health <- function() {\n  \n  current_memory <- .MONITORING_STATE$current_memory_mb\n  memory_limit <- 3072  # Railway 3GB limit\n  \n  memory_health <- list(\n    current_usage_mb = current_memory,\n    limit_mb = memory_limit,\n    usage_percent = (current_memory / memory_limit) * 100,\n    available_mb = memory_limit - current_memory,\n    \n    # Health status\n    status = if (current_memory > .MONITORING_CONFIG$memory_critical_mb) {\n      \"critical\"\n    } else if (current_memory > .MONITORING_CONFIG$memory_warning_mb) {\n      \"warning\"\n    } else {\n      \"healthy\"\n    },\n    \n    # Memory pressure analysis\n    pressure_level = calculate_memory_pressure(),\n    gc_frequency = get_gc_frequency(),\n    \n    # Memory trend analysis\n    trend = analyze_memory_trend()\n  )\n  \n  return(memory_health)\n}\n\n#' Check database health\ncheck_database_health <- function() {\n  \n  database_health <- list(\n    status = \"unknown\",\n    connection_count = 0,\n    response_time_ms = 0,\n    query_success_rate = 100,\n    last_error = NULL\n  )\n  \n  tryCatch({\n    # Try to get database performance stats if available\n    if (exists(\"get_database_performance_stats\")) {\n      db_stats <- get_database_performance_stats()\n      database_health$status <- \"healthy\"\n      database_health$connection_count <- db_stats$connection_stats$active_connections %||% 0\n      database_health$response_time_ms <- db_stats$connection_stats$avg_response_time_ms %||% 0\n      database_health$query_success_rate <- db_stats$query_success_rate %||% 100\n    } else {\n      database_health$status <- \"monitoring_unavailable\"\n    }\n    \n  }, error = function(e) {\n    database_health$status <- \"error\"\n    database_health$last_error <- e$message\n  })\n  \n  return(database_health)\n}\n\n#' Check cache health\ncheck_cache_health <- function() {\n  \n  cache_health <- list(\n    status = \"unknown\",\n    hit_rate_percent = 0,\n    memory_usage_mb = 0,\n    total_keys = 0,\n    redis_connected = FALSE\n  )\n  \n  tryCatch({\n    # Try to get cache stats if available\n    if (exists(\"get_cache_stats\")) {\n      cache_stats <- get_cache_stats()\n      cache_health$status <- \"healthy\"\n      cache_health$hit_rate_percent <- cache_stats$hit_rate %||% 0\n      cache_health$memory_usage_mb <- cache_stats$memory_usage_mb %||% 0\n      cache_health$total_keys <- cache_stats$total_keys %||% 0\n      cache_health$redis_connected <- cache_stats$redis_connected %||% FALSE\n    } else {\n      cache_health$status <- \"monitoring_unavailable\"\n    }\n    \n  }, error = function(e) {\n    cache_health$status <- \"error\"\n    cache_health$last_error <- e$message\n  })\n  \n  return(cache_health)\n}\n\n#' Check response health\ncheck_response_health <- function() {\n  \n  # Analyze recent response times\n  recent_performance <- get_recent_performance_data(1)  # Last hour\n  \n  response_times <- sapply(recent_performance, function(x) {\n    if (x$metric_type == \"response_time\") x$value else NA\n  })\n  \n  response_times <- response_times[!is.na(response_times)]\n  \n  response_health <- list(\n    avg_response_time_ms = if (length(response_times) > 0) mean(response_times) else 0,\n    max_response_time_ms = if (length(response_times) > 0) max(response_times) else 0,\n    response_count = length(response_times),\n    \n    status = if (length(response_times) == 0) {\n      \"no_data\"\n    } else if (mean(response_times) > .MONITORING_CONFIG$response_time_critical_ms) {\n      \"critical\"\n    } else if (mean(response_times) > .MONITORING_CONFIG$response_time_warning_ms) {\n      \"warning\"\n    } else {\n      \"healthy\"\n    }\n  )\n  \n  return(response_health)\n}\n\n#' Check academic context health\ncheck_academic_context_health <- function() {\n  \n  current_time <- Sys.time()\n  brazil_time <- as.POSIXct(format(current_time, tz = .MONITORING_CONFIG$timezone), \n                           tz = .MONITORING_CONFIG$timezone)\n  \n  is_peak <- is_academic_peak_hour(brazil_time)\n  is_academic_day <- weekdays(brazil_time) %in% c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\")\n  \n  # Analyze user activity patterns\n  recent_sessions <- get_recent_session_data(1)  # Last hour\n  \n  academic_health <- list(\n    current_brazil_time = brazil_time,\n    is_peak_hour = is_peak,\n    is_academic_day = is_academic_day,\n    active_sessions = length(unique(sapply(recent_sessions, function(x) x$session_id))),\n    expected_load = if (is_peak && is_academic_day) \"high\" else \"normal\",\n    \n    status = \"healthy\"  # Could be enhanced with academic-specific health checks\n  )\n  \n  return(academic_health)\n}\n\n#' Check Railway-specific health\ncheck_railway_health <- function() {\n  \n  railway_health <- list(\n    deployment_region = Sys.getenv(\"RAILWAY_REGION\", \"unknown\"),\n    service_id = Sys.getenv(\"RAILWAY_SERVICE_ID\", \"unknown\"),\n    environment = Sys.getenv(\"RAILWAY_ENVIRONMENT\", \"unknown\"),\n    \n    # Resource utilization relative to Railway limits\n    memory_utilization_percent = (.MONITORING_STATE$current_memory_mb / 3072) * 100,\n    \n    status = if (.MONITORING_STATE$current_memory_mb > 2764) {\n      \"critical\"  # 90% of Railway limit\n    } else if (.MONITORING_STATE$current_memory_mb > 2304) {\n      \"warning\"   # 75% of Railway limit\n    } else {\n      \"healthy\"\n    }\n  )\n  \n  return(railway_health)\n}\n\n#' Calculate overall health score\ncalculate_overall_health_score <- function(basic_health, memory_health, \n                                          database_health, cache_health,\n                                          response_health, academic_health, \n                                          railway_health) {\n  \n  score <- 100\n  \n  # Memory health impact (25% weight)\n  if (memory_health$status == \"critical\") score <- score - 25\n  else if (memory_health$status == \"warning\") score <- score - 10\n  \n  # Database health impact (20% weight)\n  if (database_health$status == \"error\") score <- score - 20\n  else if (database_health$response_time_ms > 2000) score <- score - 10\n  \n  # Response health impact (20% weight)\n  if (response_health$status == \"critical\") score <- score - 20\n  else if (response_health$status == \"warning\") score <- score - 10\n  \n  # Cache health impact (15% weight)\n  if (cache_health$status == \"error\") score <- score - 15\n  else if (cache_health$hit_rate_percent < 50) score <- score - 8\n  \n  # Railway health impact (10% weight)\n  if (railway_health$status == \"critical\") score <- score - 10\n  else if (railway_health$status == \"warning\") score <- score - 5\n  \n  # Academic context impact (10% weight)\n  # Academic health is generally informational, minor impact\n  \n  return(max(0, min(100, score)))\n}\n\n#' Generate health recommendations\ngenerate_health_recommendations <- function(basic_health, memory_health, \n                                          database_health, cache_health) {\n  \n  recommendations <- character(0)\n  \n  # Memory recommendations\n  if (memory_health$status == \"critical\") {\n    recommendations <- c(recommendations, \n                        \"URGENT: Memory usage critical - perform garbage collection and reduce data in memory\")\n  } else if (memory_health$status == \"warning\") {\n    recommendations <- c(recommendations,\n                        \"Warning: High memory usage - consider optimizing data structures\")\n  }\n  \n  # Database recommendations\n  if (database_health$status == \"error\") {\n    recommendations <- c(recommendations,\n                        \"Database connection issues detected - check connection pool and query performance\")\n  } else if (database_health$response_time_ms > 2000) {\n    recommendations <- c(recommendations,\n                        \"Slow database queries detected - review query optimization and indexing\")\n  }\n  \n  # Cache recommendations\n  if (cache_health$hit_rate_percent < 50 && cache_health$status == \"healthy\") {\n    recommendations <- c(recommendations,\n                        \"Low cache hit rate - review caching strategy and TTL settings\")\n  }\n  \n  # General performance recommendations\n  if (basic_health$uptime_hours > 168) {  # More than a week\n    recommendations <- c(recommendations,\n                        \"Consider restarting the application to clear accumulated memory\")\n  }\n  \n  return(recommendations)\n}\n\n# Utility functions\n\nis_academic_peak_hour <- function(timestamp = Sys.time()) {\n  hour <- as.numeric(format(timestamp, \"%H\"))\n  day <- weekdays(timestamp)\n  \n  is_academic_day <- day %in% c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\")\n  is_peak_hour <- hour >= .MONITORING_CONFIG$peak_hours$start && \n                  hour <= .MONITORING_CONFIG$peak_hours$end\n  \n  return(is_academic_day && is_peak_hour)\n}\n\ncalculate_uptime_hours <- function() {\n  as.numeric(difftime(Sys.time(), .MONITORING_STATE$system_start_time, units = \"hours\"))\n}\n\nupdate_real_time_counters <- function(metric_type, value) {\n  \n  # Update relevant counters based on metric type\n  switch(metric_type,\n    \"request\" = {\n      .MONITORING_STATE$total_requests <<- .MONITORING_STATE$total_requests + 1\n      if (value == 1) .MONITORING_STATE$successful_requests <<- .MONITORING_STATE$successful_requests + 1\n      else .MONITORING_STATE$failed_requests <<- .MONITORING_STATE$failed_requests + 1\n    },\n    \"error\" = {\n      .MONITORING_STATE$total_errors <<- .MONITORING_STATE$total_errors + 1\n    },\n    \"memory_usage\" = {\n      .MONITORING_STATE$current_memory_mb <<- value\n    },\n    \"active_sessions\" = {\n      .MONITORING_STATE$active_sessions <<- value\n    }\n  )\n}\n\ncheck_performance_thresholds <- function(metric_type, value, performance_record) {\n  \n  # Check various performance thresholds and generate alerts\n  if (metric_type == \"memory_usage\" && value > .MONITORING_CONFIG$memory_warning_mb) {\n    generate_alert(\"memory_warning\", paste(\"High memory usage:\", round(value, 1), \"MB\"), performance_record)\n  }\n  \n  if (metric_type == \"response_time\" && value > .MONITORING_CONFIG$response_time_warning_ms) {\n    generate_alert(\"response_time_warning\", paste(\"Slow response time:\", round(value, 1), \"ms\"), performance_record)\n  }\n}\n\ngenerate_alert <- function(alert_type, message, context = NULL) {\n  \n  # Check alert cooldown\n  if (is_alert_in_cooldown(alert_type)) {\n    return()\n  }\n  \n  alert <- list(\n    timestamp = Sys.time(),\n    type = alert_type,\n    message = message,\n    context = context,\n    severity = classify_alert_severity(alert_type)\n  )\n  \n  # Add to current alerts\n  .MONITORING_STATE$current_alerts[[length(.MONITORING_STATE$current_alerts) + 1]] <<- alert\n  \n  # Log alert\n  cat(\"\ud83d\udea8 ALERT [\", alert$severity, \"]:\", message, \"\\n\")\n}\n\nis_alert_in_cooldown <- function(alert_type) {\n  # Check if this alert type was recently triggered\n  cooldown_minutes <- .MONITORING_CONFIG$alert_cooldown_minutes\n  cutoff_time <- Sys.time() - (cooldown_minutes * 60)\n  \n  recent_alerts <- Filter(function(alert) {\n    alert$type == alert_type && alert$timestamp > cutoff_time\n  }, .MONITORING_STATE$current_alerts)\n  \n  return(length(recent_alerts) > 0)\n}\n\nclassify_alert_severity <- function(alert_type) {\n  critical_types <- c(\"memory_critical\", \"database_down\", \"system_failure\")\n  warning_types <- c(\"memory_warning\", \"response_time_warning\", \"cache_miss_high\")\n  \n  if (alert_type %in% critical_types) return(\"CRITICAL\")\n  if (alert_type %in% warning_types) return(\"WARNING\")\n  return(\"INFO\")\n}\n\nlog_performance_metric <- function(performance_record) {\n  # In production, this would log to a structured logging system\n  # For now, we'll use a simple console log\n  if (.MONITORING_CONFIG$performance_logging) {\n    cat(\"[PERF]\", format(performance_record$timestamp, \"%Y-%m-%d %H:%M:%S\"),\n        \"|\", performance_record$metric_type, \":\", performance_record$value, \"\\n\")\n  }\n}\n\nget_recent_performance_data <- function(hours = 1) {\n  cutoff_time <- Sys.time() - (hours * 3600)\n  \n  Filter(function(record) {\n    record$timestamp > cutoff_time\n  }, .MONITORING_STATE$performance_history)\n}\n\nget_recent_session_data <- function(hours = 1) {\n  # This would typically come from user session tracking\n  # For now, return a placeholder\n  return(list())\n}\n\ncalculate_memory_pressure <- function() {\n  usage_percent <- (.MONITORING_STATE$current_memory_mb / 3072) * 100\n  \n  if (usage_percent > 90) return(\"critical\")\n  if (usage_percent > 75) return(\"high\")\n  if (usage_percent > 50) return(\"moderate\")\n  return(\"low\")\n}\n\nget_gc_frequency <- function() {\n  # This would track garbage collection frequency\n  # For now, return a placeholder\n  return(\"normal\")\n}\n\nanalyze_memory_trend <- function() {\n  # Analyze memory usage trend over time\n  # For now, return a placeholder\n  return(\"stable\")\n}\n\nperform_detailed_health_analysis <- function() {\n  # This would perform deep system analysis\n  # For now, return basic analysis\n  return(list(\n    analysis_type = \"basic\",\n    recommendations_count = 0,\n    analysis_duration_ms = 50\n  ))\n}\n\ncheck_health_alerts <- function(health_report) {\n  # Generate alerts based on health report\n  if (health_report$overall_score < 70) {\n    generate_alert(\"health_score_low\", \n                  paste(\"System health score is low:\", round(health_report$overall_score, 1)))\n  }\n}\n\nget_current_system_status <- function() {\n  list(\n    uptime_hours = calculate_uptime_hours(),\n    memory_usage_mb = .MONITORING_STATE$current_memory_mb,\n    active_sessions = .MONITORING_STATE$active_sessions,\n    total_requests = .MONITORING_STATE$total_requests,\n    success_rate = if (.MONITORING_STATE$total_requests > 0) {\n      (.MONITORING_STATE$successful_requests / .MONITORING_STATE$total_requests) * 100\n    } else 100\n  )\n}\n\n# Placeholder functions for dashboard components\ngenerate_performance_timeline <- function(hours) {\n  list(status = \"generated\", data_points = length(.MONITORING_STATE$performance_history))\n}\n\nanalyze_resource_utilization <- function(hours) {\n  list(status = \"analyzed\", timeframe_hours = hours)\n}\n\nanalyze_user_activity_patterns <- function(hours) {\n  list(status = \"analyzed\", patterns_found = 0)\n}\n\nanalyze_database_performance <- function(hours) {\n  list(status = \"analyzed\", slow_queries = 0)\n}\n\nanalyze_cache_performance <- function(hours) {\n  list(status = \"analyzed\", hit_rate = .MONITORING_STATE$cache_hit_rate)\n}\n\nanalyze_error_patterns <- function(hours) {\n  list(status = \"analyzed\", error_count = .MONITORING_STATE$total_errors)\n}\n\nanalyze_academic_usage_patterns <- function(hours) {\n  list(status = \"analyzed\", peak_usage_detected = is_academic_peak_hour())\n}\n\nget_railway_specific_metrics <- function(hours) {\n  list(status = \"collected\", memory_utilization_percent = (.MONITORING_STATE$current_memory_mb / 3072) * 100)\n}\n\ngenerate_performance_predictions <- function() {\n  list(status = \"generated\", predictions_available = FALSE)\n}\n\nget_alert_summary <- function(hours) {\n  cutoff_time <- Sys.time() - (hours * 3600)\n  \n  recent_alerts <- Filter(function(alert) {\n    alert$timestamp > cutoff_time\n  }, .MONITORING_STATE$current_alerts)\n  \n  list(\n    total_alerts = length(recent_alerts),\n    active_alerts = recent_alerts,\n    critical_count = length(Filter(function(a) a$severity == \"CRITICAL\", recent_alerts)),\n    warning_count = length(Filter(function(a) a$severity == \"WARNING\", recent_alerts))\n  )\n}\n\n#' Get comprehensive monitoring statistics\n#' @return List with all monitoring metrics and status\n#' @export\nget_monitoring_statistics <- function() {\n  \n  list(\n    system_status = .MONITORING_STATE,\n    config = .MONITORING_CONFIG,\n    uptime_hours = calculate_uptime_hours(),\n    performance_data_points = length(.MONITORING_STATE$performance_history),\n    active_alerts = length(.MONITORING_STATE$current_alerts),\n    last_health_check = .MONITORING_STATE$last_health_check,\n    monitoring_active = TRUE\n  )\n}\n\ncat(\"\ud83d\udcc8 Application Monitoring System loaded - Week 8 Performance Implementation\\n\")\ncat(\"   Comprehensive monitoring for Brazilian Legislative Monitor on Railway\\n\")\n\n# Define the %||% operator if not already defined\nif (!exists(\"%||%\")) {\n  `%||%` <- function(x, y) if (is.null(x)) y else x\n}"